import { resize } from "@motionone/dom"
import { ControlType, RenderTarget, addPropertyControls, withCSS } from "framer"
import {
    LayoutGroup,
    animate,
    frame,
    mix,
    motion,
    useInView,
    useMotionValue,
    usePageInView,
    useTransform,
    wrap,
} from "framer-motion"
import type {
    MotionStyle,
    MotionValue,
    PanInfo,
    Transition,
} from "framer-motion"
import {
    Children,
    cloneElement,
    memo,
    startTransition,
    useCallback,
    useEffect,
    useLayoutEffect,
    useRef,
    useState,
} from "react"
import type {
    ComponentType,
    CSSProperties,
    ReactElement,
    ReactNode,
    Ref,
} from "react"
import { useEffectEvent } from "use-effect-event"

const slideshowClassName = "framer-slideshow"
const slideshowAxisXClassName = "framer-slideshow-axis-x"
const slideshowAxisYClassName = "framer-slideshow-axis-y"
const slideshowDirectionMultiplierVariable = "--framer-dir-multiplier"
const slideshowDirectionMultiplier = `var(${slideshowDirectionMultiplierVariable}, -1)`

type Direction = "left" | "right" | "top" | "bottom"
type WritingDirection = "ltr" | "rtl"
type DirectionModifier = -1 | 1
type Alignment = "flex-start" | "center" | "flex-end"
type CrossAxisSizing = "fill" | "fit"
type ArrowPosition =
    | "auto"
    | "top-left"
    | "top-mid"
    | "top-right"
    | "bottom-left"
    | "bottom-mid"
    | "bottom-right"

interface EffectsOptions {
    effectsOpacity: number
    effectsScale: number
    effectsRotate: number
    effectsPerspective: number
    effectsHover: boolean
    playOffscreen: boolean
}

interface FadeOptions {
    fadeContent: boolean
    overflow: boolean
    fadeWidth: number
    fadeInset: number
    fadeAlpha: number
}

interface ArrowOptions {
    showMouseControls: boolean
    arrowSize: number
    arrowRadius?: number
    arrowFill: string
    leftArrow?: string
    rightArrow?: string
    arrowShouldSpace?: boolean
    arrowShouldFadeIn?: boolean
    arrowPosition?: ArrowPosition
    arrowPadding?: number
    arrowGap?: number
    arrowPaddingTop?: number
    arrowPaddingRight?: number
    arrowPaddingBottom?: number
    arrowPaddingLeft?: number
}

interface ProgressOptions {
    showProgressDots: boolean
    dotSize?: number
    dotsInset?: number
    dotsRadius?: number
    dotsPadding?: number
    dotsGap?: number
    dotsFill?: string
    dotsBackground?: string
    dotsActiveOpacity?: number
    dotsOpacity?: number
    dotsBlur?: number
}

interface SlideshowProps {
    slots?: ReactElement[]
    startFrom: number
    direction: Direction
    effectsOptions: EffectsOptions
    autoPlayControl: boolean
    dragControl: boolean
    infinity?: boolean
    widthSizing: CrossAxisSizing
    heightSizing: CrossAxisSizing
    alignment: Alignment
    gap: number
    padding: number
    paddingPerSide?: boolean
    paddingTop?: number
    paddingRight?: number
    paddingBottom?: number
    paddingLeft?: number
    itemAmount: number
    fadeOptions: FadeOptions
    intervalControl: number
    transitionControl: Transition
    arrowOptions: ArrowOptions
    borderRadius: number
    progressOptions: ProgressOptions
    style?: MotionStyle
}

interface SizeState {
    parent: number | null
    children: number | null
    item: number | null
    itemWidth: number | null
    itemHeight: number | null
    viewportLength: number | null
}

function SlideshowWithoutCSS(props: SlideshowProps) {
    /**
     * Properties
     */
    const {
        slots = [],
        startFrom,
        direction,
        effectsOptions,
        autoPlayControl,
        dragControl,
        widthSizing,
        heightSizing,
        alignment,
        gap,
        padding,
        paddingPerSide,
        paddingTop,
        paddingRight,
        paddingBottom,
        paddingLeft,
        itemAmount: visibleItemsCount,
        fadeOptions,
        intervalControl,
        transitionControl,
        arrowOptions,
        borderRadius,
        progressOptions,
        style,
    } = props

    const {
        effectsOpacity,
        effectsScale,
        effectsRotate,
        effectsPerspective,
        effectsHover,
        playOffscreen,
    } = effectsOptions

    const { fadeContent, overflow, fadeWidth, fadeInset, fadeAlpha } =
        fadeOptions

    const {
        showMouseControls,
        arrowSize,
        arrowRadius,
        arrowFill,
        leftArrow,
        rightArrow,
        arrowShouldSpace = true,
        arrowShouldFadeIn = false,
        arrowPosition,
        arrowPadding,
        arrowGap,
        arrowPaddingTop,
        arrowPaddingRight,
        arrowPaddingBottom,
        arrowPaddingLeft,
    } = arrowOptions

    const {
        showProgressDots,
        dotSize,
        dotsInset,
        dotsRadius,
        dotsPadding,
        dotsGap,
        dotsFill,
        dotsBackground,
        dotsActiveOpacity,
        dotsOpacity,
        dotsBlur,
    } = progressOptions

    const paddingValue = paddingPerSide
        ? `${paddingTop}px ${paddingRight}px ${paddingBottom}px ${paddingLeft}px`
        : `${padding}px`

    /**
     * Checks
     */
    const isCanvas = RenderTarget.current() === RenderTarget.canvas
    // Remove empty slots (such as hidden layers)
    const filteredSlots = slots.filter(Boolean)
    const totalItemsCount = Children.count(filteredSlots)
    const hasChildren = totalItemsCount > 0

    /**
     * Empty state for Canvas
     */
    if (!hasChildren) {
        return (
            <section style={placeholderStyles}>
                <div style={emojiStyles}>⭐️</div>
                <p style={titleStyles}>Connect to Content</p>
                <p style={subtitleStyles}>
                    Add layers or components to make infinite auto-playing
                    slideshows.
                </p>
            </section>
        )
    }

    /**
     * Refs, State
     */
    const parentRef = useRef<HTMLElement | null>(null)
    const parentSizeRef = useRef<{ width: number; height: number } | null>(null)
    const parentRefFn = useCallback((node: HTMLElement | null) => {
        parentRef.current = node
        if (parentRef.current) scheduleMeasure()
    }, [])

    const [size, setSize] = useState<SizeState>({
        parent: null,
        children: null,
        item: null,
        itemWidth: null,
        itemHeight: null,
        viewportLength: null,
    })

    const isHorizontal = direction === "left" || direction === "right"
    const writingDirection = useWritingDirection()
    const rtlDirectionModifier =
        isHorizontal && writingDirection === "rtl" ? -1 : 1

    /* For pausing on hover */
    const [isHovering, setIsHovering] = useState(false)
    const [shouldPlayOnHover, setShouldPlayOnHover] = useState(autoPlayControl)

    /* For cursor updates */
    const [isMouseDown, setIsMouseDown] = useState(false)

    /* For SSR / initial render */
    const isInitialized =
        size?.item !== null &&
        size?.parent !== null &&
        writingDirection !== null

    /**
     * Array for children
     */
    // Normally, the user would provide like 10 slides (totalItemsCount == 10) and only show one at a
    // time (visibleItemsCount == 1). In these cases, extraCopyCount == 1, and we only render 3 extra
    // duplicates in the live mode or no duplicates at all in the SSR or on Canvas.
    // However, sometimes, the user might things like
    // - provide totalItemsCount = 5, visibleItemsCount = 3, startFrom = 4 → we need one more duplicate to continue the loop
    //   and render two more slides
    // - or: totalItemsCount = 2, visibleItemsCount = 10 → we need three more duplicates to fill the whole view of the slideshow
    // In these cases, we produce extra copies of the children.
    const extraCopyCount = Math.ceil(
        (startFrom + visibleItemsCount) / totalItemsCount
    )
    let dupedChildren: ReactNode[] = []
    let duplicateBy = extraCopyCount * 4

    if (isCanvas || !isInitialized) {
        duplicateBy = extraCopyCount
    }

    /**
     * Measure parent and derive item sizes
     */
    /* Calculate the new value to animate to */
    const [currentItem, setCurrentItem] = useState(startFrom + totalItemsCount)
    /* Animate whenever currentItem changes */
    useEffect(() => {
        if (!size.item || !writingDirection) return
        const computedNewPosition =
            -1 *
            currentItem *
            ((size.item ?? 0) + gap) *
            (writingDirection === "rtl" ? -1 : 1)
        if (xOrY.get() !== computedNewPosition) {
            animate(xOrY, computedNewPosition, transitionControl)
        }
    }, [currentItem, size.item, gap, writingDirection])

    const measure = () => {
        const parentSize = parentSizeRef.current
        if (!parentSize) return

        const parentWidth = parentSize.width
        const parentHeight = parentSize.height
        const parentLength = isHorizontal ? parentWidth : parentHeight
        const visibleItems = Math.max(1, visibleItemsCount)
        // Given that slides are uniformly sized, we can calculate their size based on the parent’s size.
        // This saves us from the trouble of reading child boxes, which is surprisingly tricky:
        // - offsetWidth/Height is a rounded integer, which leads to
        //   off-by-a-few-px positioning errors when the parent has a fractional width
        // - getBoundingClientRect() returns a fractional width/height, but
        //   with transforms applied (whereas we need a pre-transform one)
        const itemSize = Math.max(
            0,
            (parentLength - gap * (visibleItems - 1)) / visibleItems
        )
        const childrenLength = totalItemsCount * (itemSize + gap)
        const itemWidth = isHorizontal ? itemSize : parentWidth
        const itemHeight = isHorizontal ? parentHeight : itemSize

        const viewportLength = isHorizontal
            ? Math.max(
                  document.documentElement.clientWidth || 0,
                  window.innerWidth || 0,
                  parentWidth
              )
            : Math.max(
                  document.documentElement.clientHeight || 0,
                  window.innerHeight || 0,
                  parentHeight
              )
        setSize({
            parent: parentLength,
            children: childrenLength,
            item: itemSize,
            itemWidth,
            itemHeight,
            viewportLength,
        })
    }

    const scheduleMeasure = useEffectEvent(() => {
        frame.read(measure, false, true)
    })

    /* Re-measure when some layout-affecting props change */
    useLayoutEffect(() => {
        scheduleMeasure()
    }, [
        filteredSlots.length,
        visibleItemsCount,
        gap,
        direction,
        padding,
        paddingPerSide,
        paddingTop,
        paddingRight,
        paddingBottom,
        paddingLeft,
    ])

    /** Re-measure when the parent is resized */
    useEffect(() => {
        const node = parentRef.current
        if (!node) return

        return resize(node, ({ size }) => {
            // Note: we’re getting the size from the resize observer, which is the only reliable way
            // to get a size that’s 1) not rounded to the nearest integer and 2) not affected by transforms.
            // - offsetWidth/Height is rounded to the nearest integer, which leads to off-by-a-few-px positioning errors: https://framer-team.slack.com/archives/C01B14R6E22/p1777506572882389
            // - getBoundingClientRect() returns a fractional width/height, but with transforms applied,
            //   which breaks everything if the parent has a scale transform applied to it (eg as a part of an effect)
            parentSizeRef.current = size
            if (!size.width || !size.height) return
            scheduleMeasure()
        })
    }, [])

    /**
     * Animation, pagination
     */
    const childrenSize = isCanvas ? 0 : size?.children
    const [isDragging, setIsDragging] = useState(false)

    /* Check for browser window visibility */
    /* Otherwise, it will re-play all the item increments */
    const visibilityRef = useRef(null)
    const isInView = useInView(visibilityRef)
    const isVisible = usePageInView() && isInView

    /* The x and y values to start from */
    const xOrY = useMotionValue(childrenSize)

    /* Wrapped values for infinite looping */
    /* Instead of 0 to a negative full duplicated row, we start with an offset */
    const wrappedXOrY = !isCanvas
        ? useTransform(xOrY, (value) => {
              const resolvedChildrenSize = childrenSize ?? 0
              const resolvedValue = value ?? 0

              const wrapped = wrap(
                  -resolvedChildrenSize * rtlDirectionModifier,
                  -resolvedChildrenSize * rtlDirectionModifier * 2,
                  resolvedValue
              )
              return Number.isNaN(wrapped) ? 0 : wrapped
          })
        : useMotionValue(0)
    /* Convert the current item to a wrapping index for dots */
    const wrappedIndex = wrap(0, totalItemsCount, currentItem)

    /**
     * Page item methods
     * Switching, deltas, autoplaying
     */
    /* Page navigation functions */
    const setDelta = (delta: number) => {
        startTransition(() => setCurrentItem((item) => item + delta))
    }

    const setPage = (index: number) => {
        const currentItemWrapped = wrap(0, totalItemsCount, currentItem)

        const goto = index - currentItemWrapped
        startTransition(() => setCurrentItem((item) => item + goto))
    }

    /* Autoplay: schedule one tick at a time whenever currentItem changes */
    const autoplayStep =
        (direction === "right" || direction === "bottom" ? -1 : 1) *
        rtlDirectionModifier
    const canAutoplay =
        autoPlayControl &&
        shouldPlayOnHover &&
        (playOffscreen || isVisible) &&
        !isCanvas &&
        totalItemsCount > 1 &&
        !isDragging &&
        isInitialized
    useEffect(() => {
        if (!canAutoplay) return

        const timeoutId = setTimeout(() => {
            setDelta(autoplayStep)
        }, intervalControl * 1000)

        return () => clearTimeout(timeoutId)
    }, [canAutoplay, autoplayStep, intervalControl, currentItem])

    /**
     * Drag
     */
    const handleDragStart = () => {
        startTransition(() => setIsDragging(true))
    }
    const handleDragEnd = (
        _event: MouseEvent | TouchEvent | PointerEvent,
        { offset, velocity }: PanInfo
    ) => {
        startTransition(() => setIsDragging(false))

        const offsetXorY = isHorizontal ? offset.x : offset.y
        const velocityThreshold = 200 // Based on testing, can be tweaked or could be 0
        const velocityXorY = isHorizontal ? velocity.x : velocity.y

        const isHalfOfNext = offsetXorY < -size.item / 2
        const isHalfOfPrev = offsetXorY > size.item / 2

        /* In case you drag more than 1 item left or right */
        const normalizedOffset = Math.abs(offsetXorY)
        const itemDelta = Math.round(normalizedOffset / size.item)

        /* Minimum delta is 1 to initiate a page switch */
        /* For velocity use only */
        const itemDeltaFromOne = itemDelta === 0 ? 1 : itemDelta

        /* For quick flicks, even with low offsets */
        if (velocityXorY > velocityThreshold) {
            setDelta(-itemDeltaFromOne * rtlDirectionModifier)
        } else if (velocityXorY < -velocityThreshold) {
            setDelta(itemDeltaFromOne * rtlDirectionModifier)
        } else {
            /* For dragging over half of the current item with 0 velocity */
            if (isHalfOfNext) {
                setDelta(itemDelta * rtlDirectionModifier)
            }
            if (isHalfOfPrev) {
                setDelta(-itemDelta * rtlDirectionModifier)
            }
        }
    }

    // Static/canvas layout: translate by a deterministic CSS calc so the starting slide is visible
    // without relying on runtime measurements.
    const staticStartFrom = Math.max(
        0,
        Math.min(startFrom ?? 0, Math.max(0, totalItemsCount - 1))
    )
    const staticPercentOffset = (staticStartFrom * 100) / visibleItemsCount
    const staticPixelOffset = (staticStartFrom * gap) / visibleItemsCount

    /* Create copies of our children to create a perfect loop */
    let childCounter = 0

    /**
     * Sizing
     * */
    const columnOrRowValue = `calc(${100 / visibleItemsCount}% - ${gap}px + ${gap / visibleItemsCount}px)`

    // How slides are sized on the cross axis. 
    // Fit allows alignment if the slotted item is smaller than the slide bounds.
    // Fill is 100%.
    const crossAxisSizing = isHorizontal ? heightSizing : widthSizing

    /**
     * Nested array to create duplicates of the children for infinite looping
     * These are wrapped around, and start at a full "page" worth of offset
     * as defined above.
     */
    for (let index = 0; index < duplicateBy; index++) {
        dupedChildren = dupedChildren.concat(
            Children.map(filteredSlots, (child, childIndex) => {
                const childElement = child as ReactElement<SlideChildProps>
                // If fit we capture the child's dimension for canvas rendering.
                // It will be undefined in code gen so the class will set the dimension.
                const crossAxisSize =
                    crossAxisSizing === "fit"
                        ? isHorizontal
                            ? childElement.props?.height
                            : childElement.props?.width
                        : "100%"

                return (
                    <Slide
                        key={index + childIndex + "lg"}
                        slideKey={index + childIndex + "lg"}
                        index={index}
                        width={
                            isHorizontal
                                ? visibleItemsCount > 1
                                    ? columnOrRowValue
                                    : "100%"
                                : crossAxisSize
                        }
                        height={
                            !isHorizontal
                                ? visibleItemsCount > 1
                                    ? columnOrRowValue
                                    : "100%"
                                : crossAxisSize
                        }
                        size={size}
                        child={child}
                        numChildren={filteredSlots?.length}
                        wrappedXOrY={wrappedXOrY}
                        childCounter={childCounter++}
                        gap={gap}
                        isCanvas={isCanvas}
                        isInitialized={isInitialized}
                        isHorizontal={isHorizontal}
                        effectsOpacity={effectsOpacity}
                        effectsScale={effectsScale}
                        effectsRotate={effectsRotate}
                        writingDirection={writingDirection}
                        rtlDirectionModifier={rtlDirectionModifier}
                    >
                        {index + childIndex}
                    </Slide>
                )
            })
        )
    }

    /**
     * Fades with masks
     */
    const fadeDirection = isHorizontal ? "to right" : "to bottom"
    const fadeWidthStart = fadeWidth / 2
    const fadeWidthEnd = 100 - fadeWidth / 2
    const fadeInsetStart = clamp(fadeInset, 0, fadeWidthStart)
    const fadeInsetEnd = 100 - fadeInset

    const fadeMask = `linear-gradient(${fadeDirection}, rgba(0, 0, 0, ${fadeAlpha}) ${fadeInsetStart}%, rgba(0, 0, 0, 1) ${fadeWidthStart}%, rgba(0, 0, 0, 1) ${fadeWidthEnd}%, rgba(0, 0, 0, ${fadeAlpha}) ${fadeInsetEnd}%)`

    /**
     * Dots
     */
    const dots: ReactElement[] = []
    const dotsBlurStyle: CSSProperties = {}

    if (showProgressDots) {
        for (let i = 0; i < filteredSlots?.length; i++) {
            dots.push(
                <Dot
                    key={i}
                    dotStyle={{
                        ...dotStyle,
                        width: dotSize,
                        height: dotSize,
                        backgroundColor: dotsFill,
                    }}
                    buttonStyle={baseButtonStyles}
                    selectedOpacity={dotsActiveOpacity}
                    opacity={dotsOpacity}
                    disabled={!isCanvas && !isInitialized}
                    onClick={() => setPage(i)}
                    wrappedIndex={
                        isCanvas || !isInitialized
                            ? staticStartFrom
                            : wrappedIndex
                    }
                    total={totalItemsCount}
                    index={i}
                    gap={dotsGap}
                    padding={dotsPadding}
                    isHorizontal={isHorizontal}
                />
            )
        }

        if (dotsBlur > 0) {
            dotsBlurStyle.backdropFilter =
                dotsBlurStyle.WebkitBackdropFilter = `blur(${dotsBlur}px)`
        }
    }

    const dragProps =
        isInitialized && dragControl
            ? {
                  drag: isHorizontal ? ("x" as const) : ("y" as const),
                  onDragStart: handleDragStart,
                  onDragEnd: handleDragEnd,
                  dragDirectionLock: true,
                  values: {
                      x: xOrY,
                      y: xOrY,
                  },
                  dragMomentum: false,
              }
            : {}

    const arrowHasTop =
        arrowPosition === "top-left" ||
        arrowPosition === "top-mid" ||
        arrowPosition === "top-right"

    const arrowHasBottom =
        arrowPosition === "bottom-left" ||
        arrowPosition === "bottom-mid" ||
        arrowPosition === "bottom-right"

    const arrowHasLeft =
        arrowPosition === "top-left" || arrowPosition === "bottom-left"

    const arrowHasRight =
        arrowPosition === "top-right" || arrowPosition === "bottom-right"

    const arrowHasMid =
        arrowPosition === "top-mid" ||
        arrowPosition === "bottom-mid" ||
        arrowPosition === "auto"

    const leftArrowSrc =
        leftArrow ||
        "https://framerusercontent.com/images/6tTbkXggWgQCAJ4DO2QEdXXmgM.svg?arrow=left"
    const rightArrowSrc =
        rightArrow ||
        "https://framerusercontent.com/images/11KSGbIZoRSg4pjdnUoif6MKHI.svg?arrow=right"

    return (
        <section
            className={`${slideshowClassName} ${isHorizontal ? slideshowAxisXClassName : slideshowAxisYClassName}`}
            style={{
                ...containerStyle,
                padding: paddingValue,
                WebkitMaskImage: fadeContent ? fadeMask : undefined,
                maskImage: fadeContent ? fadeMask : undefined,
                userSelect: "none",
            }}
            onMouseEnter={() => {
                setIsHovering(true)
                if (!effectsHover) setShouldPlayOnHover(false)
            }}
            onMouseLeave={() => {
                setIsHovering(false)
                if (!effectsHover) setShouldPlayOnHover(true)
            }}
            onMouseDown={(event) => {
                // Preventdefault fixes the cursor switching to text on drag on safari
                event.preventDefault()
                startTransition(() => setIsMouseDown(true))
            }}
            onMouseUp={() => startTransition(() => setIsMouseDown(false))}
            ref={visibilityRef}
        >
            <div
                style={{
                    width: "100%",
                    height: "100%",
                    margin: 0,
                    padding: "inherit",
                    position: "absolute",
                    inset: 0,
                    overflow: overflow ? "visible" : "hidden",
                    borderRadius: borderRadius,
                    userSelect: "none",
                    perspective: isCanvas ? "none" : effectsPerspective, // Adding the perspective onto the motion.ul directly causes issues on Safari where you can see the layers clip.
                }}
            >
                <motion.ul
                    ref={parentRefFn}
                    {...dragProps}
                    style={{
                        ...containerStyle,
                        gap: gap,
                        placeItems: alignment,
                        ...(isCanvas || !isInitialized
                            ? {
                                  transform: isHorizontal
                                      ? `translateX(calc(${slideshowDirectionMultiplier} * (${staticPercentOffset}% + ${staticPixelOffset}px)))`
                                      : `translateY(calc(${slideshowDirectionMultiplier} * (${staticPercentOffset}% + ${staticPixelOffset}px)))`,
                              }
                            : {
                                  x: isHorizontal ? wrappedXOrY : 0,
                                  y: !isHorizontal ? wrappedXOrY : 0,
                              }),
                        flexDirection: isHorizontal ? "row" : "column",
                        transformStyle:
                            effectsRotate !== 0 && !isCanvas
                                ? "preserve-3d"
                                : undefined,
                        cursor:
                            (isCanvas || isInitialized) && dragControl
                                ? isMouseDown
                                    ? "grabbing"
                                    : "grab"
                                : "auto",
                        userSelect: "none",
                        ...style,
                    }}
                >
                    {dupedChildren}
                </motion.ul>
            </div>

            <fieldset
                style={{
                    ...controlsStyles,
                }}
                aria-label="Slideshow pagination controls"
                className="framer--slideshow-controls"
            >
                <motion.div
                    style={{
                        position: "absolute",
                        display: "flex",
                        flexDirection: isHorizontal ? "row" : "column",
                        justifyContent: arrowShouldSpace
                            ? "space-between"
                            : "center",
                        gap: arrowShouldSpace ? "unset" : arrowGap,
                        opacity:
                            arrowShouldFadeIn || (!isCanvas && !isInitialized)
                                ? 0
                                : 1,
                        alignItems: "center",
                        inset: arrowPadding,
                        top: arrowShouldSpace
                            ? arrowPadding
                            : arrowHasTop
                              ? arrowPaddingTop
                              : "unset",
                        left: arrowShouldSpace
                            ? arrowPadding
                            : arrowHasLeft
                              ? arrowPaddingLeft
                              : arrowHasMid
                                ? 0
                                : "unset",
                        right: arrowShouldSpace
                            ? arrowPadding
                            : arrowHasRight
                              ? arrowPaddingRight
                              : arrowHasMid
                                ? 0
                                : "unset",
                        bottom: arrowShouldSpace
                            ? arrowPadding
                            : arrowHasBottom
                              ? arrowPaddingBottom
                              : "unset",
                    }}
                    animate={
                        isCanvas || isInitialized
                            ? arrowShouldFadeIn
                                ? { opacity: isHovering ? 1 : 0 }
                                : { opacity: 1 }
                            : { opacity: 0 }
                    }
                    transition={transitionControl}
                >
                    <motion.button
                        type="button"
                        style={{
                            ...baseButtonStyles,
                            backgroundColor: arrowFill,
                            width: arrowSize,
                            height: arrowSize,
                            borderRadius: arrowRadius,
                            rotate: !isHorizontal ? 90 : 0,
                            display: showMouseControls ? "block" : "none",
                            pointerEvents:
                                isCanvas || isInitialized ? "auto" : "none",
                            cursor:
                                isCanvas || isInitialized
                                    ? "pointer"
                                    : "default",
                        }}
                        disabled={!(isCanvas || isInitialized)}
                        onClick={() => setDelta(-1)}
                        aria-label="Previous"
                        whileTap={{ scale: 0.9 }}
                        transition={{ duration: 0.15 }}
                    >
                        <img
                            decoding="async"
                            width={arrowSize}
                            height={arrowSize}
                            src={
                                isHorizontal && writingDirection === "rtl"
                                    ? rightArrowSrc
                                    : leftArrowSrc
                            }
                            alt="Back Arrow"
                        />
                    </motion.button>
                    <motion.button
                        type="button"
                        style={{
                            ...baseButtonStyles,
                            backgroundColor: arrowFill,
                            width: arrowSize,
                            height: arrowSize,
                            borderRadius: arrowRadius,
                            rotate: !isHorizontal ? 90 : 0,
                            display: showMouseControls ? "block" : "none",
                            pointerEvents:
                                isCanvas || isInitialized ? "auto" : "none",
                            cursor:
                                isCanvas || isInitialized
                                    ? "pointer"
                                    : "default",
                        }}
                        disabled={!(isCanvas || isInitialized)}
                        onClick={() => setDelta(1)}
                        aria-label="Next"
                        whileTap={{ scale: 0.9 }}
                        transition={{ duration: 0.15 }}
                    >
                        <img
                            decoding="async"
                            width={arrowSize}
                            height={arrowSize}
                            src={
                                isHorizontal && writingDirection === "rtl"
                                    ? leftArrowSrc
                                    : rightArrowSrc
                            }
                            alt="Next Arrow"
                        />
                    </motion.button>
                </motion.div>
                {dots.length > 1 ? (
                    <motion.div
                        style={{
                            ...dotsContainerStyle,
                            left: isHorizontal ? "50%" : dotsInset,
                            top: !isHorizontal ? "50%" : "unset",
                            transform: isHorizontal
                                ? "translateX(-50%)"
                                : "translateY(-50%)",
                            flexDirection: isHorizontal ? "row" : "column",
                            bottom: isHorizontal ? dotsInset : "unset",
                            borderRadius: dotsRadius,
                            backgroundColor: dotsBackground,
                            userSelect: "none",
                            ...dotsBlurStyle,
                            // Hard-code opacity to 1 on canvas. In SSR, it will be animated from 0 to 1 in `animate`
                            opacity: isCanvas ? 1 : 0,
                            pointerEvents:
                                isCanvas || isInitialized ? "auto" : "none",
                        }}
                        animate={{ opacity: isInitialized ? 1 : 0 }}
                        transition={{ duration: 0.35, ease: "easeOut" }}
                    >
                        {dots}
                    </motion.div>
                ) : null}
            </fieldset>
        </section>
    )
}

