/* Slide Component */
interface SlideChildProps {
    style?: MotionStyle
    layoutId?: string
    ref?: Ref<HTMLElement>
    // Framer passes a slotted item's fixed size as props on the static canvas.
    width?: number | string
    height?: number | string
}

interface SlideProps {
    slideKey: string
    width: MotionStyle["width"]
    height: MotionStyle["height"]
    child: ReactElement<SlideChildProps>
    size: SizeState
    gap: number
    wrappedXOrY: MotionValue<number>
    numChildren: number
    childCounter: number
    isCanvas: boolean
    isInitialized: boolean
    effectsOpacity: number
    effectsScale: number
    effectsRotate: number
    isHorizontal: boolean
    index: number
    writingDirection: WritingDirection | null
    rtlDirectionModifier: DirectionModifier
    children?: ReactNode
}

const Slide = memo(function Component(props: SlideProps) {
    const {
        slideKey,
        width,
        height,
        child,
        size,
        gap,
        wrappedXOrY,
        numChildren,
        childCounter,
        isCanvas,
        isInitialized,
        effectsOpacity,
        effectsScale,
        effectsRotate,
        isHorizontal,
        index,
        /** "ltr" or "rtl" */
        writingDirection,
        /** -1 in RTL, 1 in LTR */
        rtlDirectionModifier,
    } = props

    const ref = useRef<HTMLElement | null>(null)

    const itemSize = size?.item ?? 0
    const parentSize = size?.parent ?? 0

    /**
     * Unique offsets + scroll range [0, 1, 1, 0]
     */
    const childOffset = (itemSize + gap) * childCounter
    const scrollRange =
        // @ivan: this was picked experimentally when fixing semi-working-but-broken RTL
        // implementation in the existing Carousel code. Don’t ask me why these specific values, I’m
        // finding it hard to fully reason about RTL in carousel :/
        (
            isHorizontal && writingDirection === "rtl"
                ? [
                      itemSize - gap,
                      0,
                      -parentSize + itemSize - gap,
                      -parentSize - gap,
                  ]
                : [-itemSize, 0, parentSize - itemSize + gap, parentSize]
        ).map((val) => val - childOffset * rtlDirectionModifier)

    /**
     * Effects
     */
    const rotateY =
        !isCanvas &&
        useTransform(
            wrappedXOrY,
            scrollRange,
            // Why flip the rotateY effect when RTL is enabled?
            //
            // Unlike other effects, rotation is vertically symmetrical. Say the user sets a 60 degree rotation.
            // The carousel will look like this:
            //   ) □ ▣ ▤ (
            // where
            // - □ ▣ ▤ are the three slides visible within the carousel,
            // - ) is an out-of-view slide to the left of the viewport,
            // - and ( is an out-of-view slide to the right of the viewport.
            // With 60° rotation, both out-of-view slides look “turned towards” the viewport,
            // which matters for the animation when the slides switch.
            //
            // If a user sets RTL, all items in the carousel will flip around. The carousel, by default, will now look like this:
            //   ( ▤ ▣ □ )
            // Notice how all slides reversed. The slide that was to the left of the viewport: ) – is now to the right of it!
            // And is now turned away from the viewport! So if we don’t flip the rotateY effect, the animation will look off.
            isHorizontal && writingDirection === "rtl"
                ? [effectsRotate, 0, 0, -effectsRotate]
                : [-effectsRotate, 0, 0, effectsRotate]
        )
    const rotateX =
        !isCanvas &&
        useTransform(wrappedXOrY, scrollRange, [
            effectsRotate,
            0,
            0,
            -effectsRotate,
        ])
    const opacity =
        !isCanvas &&
        useTransform(wrappedXOrY, scrollRange, [
            effectsOpacity,
            1,
            1,
            effectsOpacity,
        ])
    const scale =
        !isCanvas &&
        useTransform(wrappedXOrY, scrollRange, [
            effectsScale,
            1,
            1,
            effectsScale,
        ])
    const originXorY =
        !isCanvas &&
        useTransform(
            wrappedXOrY,
            scrollRange,
            // Just like above, because in RTL, the items are flipped vertically, RTL needs a separate treatment
            isHorizontal && writingDirection === "rtl"
                ? [0, 0, 1, 1]
                : [1, 1, 0, 0]
        )

    const isVisible =
        !isCanvas &&
        useTransform(wrappedXOrY, (latest) => {
            // Min and max swap in LTR vs RTL
            const min = Math.min(scrollRange[1], scrollRange[2])
            const max = Math.max(scrollRange[1], scrollRange[2])
            return latest >= min && latest <= max
        })

    useEffect(() => {
        if (!isVisible || !isInitialized) return

        function manageVisibility(visible: boolean) {
            const node = ref?.current

            if (!node) return

            // for a11y: Manage tabIndex on focusable descendants & aria-hidden on the parent.
            if (visible) {
                node.querySelectorAll<HTMLElement>("button,a").forEach((el) => {
                    const orig = el.dataset.origTabIndex
                    if (orig) el.tabIndex = Number(orig)
                    else el.removeAttribute("tabIndex")
                })
            } else {
                node.querySelectorAll<HTMLElement>("button,a").forEach((el) => {
                    const orig = el.getAttribute("tabIndex")
                    if (orig) el.dataset.origTabIndex = orig
                    el.tabIndex = -1
                })
            }
            node.setAttribute("aria-hidden", String(!visible))
        }
        manageVisibility(isVisible.get())

        return isVisible.on("change", (visible) => {
            manageVisibility(visible)
        })
    }, [isInitialized])

    const visibility = isCanvas
        ? "visible"
        : useTransform(
              wrappedXOrY,
              [
                  scrollRange[0] - size.viewportLength * rtlDirectionModifier,
                  mix(scrollRange[1], scrollRange[2], 0.5), // Mid-point between its effectless scroll offsets
                  scrollRange[3] + size.viewportLength * rtlDirectionModifier,
              ],
              ["hidden", "visible", "hidden"]
          )

    const key = slideKey + "child"
    return (
        <LayoutGroup inherit="id" id={key}>
            <li style={{ display: "contents" }}>
                {cloneElement(child, {
                    ref,
                    key,
                    style: {
                        ...child.props?.style,
                        flexShrink: 0,
                        userSelect: "none",
                        width,
                        height,
                        ...(isInitialized
                            ? {
                                  opacity,
                                  scale,
                                  originX: isHorizontal ? originXorY : 0.5,
                                  originY: !isHorizontal ? originXorY : 0.5,
                                  rotateY: isHorizontal ? rotateY : 0,
                                  rotateX: !isHorizontal ? rotateX : 0,
                                  visibility,
                              }
                            : {}),
                    },
                    layoutId: child.props.layoutId
                        ? child.props.layoutId + "-original-" + index
                        : undefined,
                })}
            </li>
        </LayoutGroup>
    )
})

/* Dot Component */
interface DotProps {
    dotStyle: React.CSSProperties
    buttonStyle: React.CSSProperties
    onClick: () => void
    disabled?: boolean
    wrappedIndex: number
    selectedOpacity: number
    opacity: number
    total: number
    index: number
    gap: number
    padding: number
    isHorizontal: boolean
}

const Dot = memo(function Dot({
    selectedOpacity,
    opacity,
    total,
    index,
    wrappedIndex,
    dotStyle,
    buttonStyle,
    gap,
    padding,
    isHorizontal,
    ...props
}: DotProps) {
    /* Check active item */
    /* Go 0—1—2—3—4—5—0 */
    const isSelected = wrappedIndex === index

    const inlinePadding = gap / 2
    const top = !isHorizontal && index !== 0 ? inlinePadding : padding
    const bottom =
        !isHorizontal && index !== total - 1 ? inlinePadding : padding

    // Use logical inline padding so RTL/LTR spacing is correct even if this subtree
    // is rendered under a different `direction` than `documentElement.dir`.
    const inlineStart = isHorizontal
        ? index === 0
            ? padding
            : inlinePadding
        : padding
    const inlineEnd = isHorizontal
        ? index === total - 1
            ? padding
            : inlinePadding
        : padding

    return (
        <button
            aria-label={`Scroll to page ${index + 1}`}
            type="button"
            {...props}
            style={{
                ...buttonStyle,
                paddingTop: top,
                paddingBottom: bottom,
                paddingInlineStart: inlineStart,
                paddingInlineEnd: inlineEnd,
            }}
        >
            <motion.div
                style={{
                    ...dotStyle,
                }}
                initial={false}
                animate={{
                    opacity: isSelected ? selectedOpacity : opacity,
                }}
                transition={{ duration: 0.3 }}
            />
        </button>
    )
})

/* Dot Styles */
const dotsContainerStyle: React.CSSProperties = {
    display: "flex",
    placeContent: "center",
    placeItems: "center",
    overflow: "hidden",
    position: "absolute",
    pointerEvents: "auto",
}

const dotStyle: React.CSSProperties = {
    borderRadius: "50%",
    background: "white",
    cursor: "pointer",
    border: "none",
    placeContent: "center",
    placeItems: "center",
    padding: 0,
}

function getWritingDirection(): "ltr" | "rtl" {
    return window?.document?.documentElement?.dir === "rtl" ? "rtl" : "ltr"
}

function useWritingDirection(): "ltr" | "rtl" | null {
    const [writingDirection, setWritingDirection] = useState<
        "ltr" | "rtl" | null
    >(null)
    // must be done this way to ensure that there isn't a mismatch with SSG
    // which leads to button images not updating for the real writing direction
    useEffect(() => {
        setWritingDirection(getWritingDirection())

        // Listen for changes to the writing direction. While uncommon on live sites, this can easily happen
        // on the canvas when switching between locales on the same page.
        return onWritingDirectionChange(() => {
            setWritingDirection(getWritingDirection())
        })
    }, [])
    return writingDirection
}

let observer: MutationObserver | null = null
const callbacks: (() => void)[] = []
function onWritingDirectionChange(callback: () => void) {
    callbacks.push(callback)

    if (!observer) {
        // A single MutationObserver watching a single attribute on a single element should be reasonably fast:
        // https://news.ycombinator.com/item?id=15274833 (note: Paul Irish)
        // https://stackoverflow.com/a/39332340
        observer = new MutationObserver(() =>
            callbacks.forEach((callback) => callback())
        )
        observer.observe(document.documentElement, {
            attributeFilter: ["dir"],
        })
    }

    // Return a function to unsubscribe from the callback
    return () => {
        callbacks.splice(callbacks.indexOf(callback), 1)
        if (callbacks.length === 0) {
            observer?.disconnect()
            observer = null
        }
    }
}
